// docTag marks a row the verdicter must NOT read as code. Empty for every
// Go kind, so code answers render byte-identically to today.
func docTag(kind string) string {
    if kind == kindDoc { return " [doc]" }
    return ""
}

// in each of the three cases: add kind to the SELECT and scan it
//   symbol : SELECT path, symbol, COALESCE(signature,''), ..., kind
//   content: SELECT path, symbol, COALESCE(body,''), content, ..., kind
//   ls     : SELECT DISTINCT path, COALESCE(commit_sha,''), kind

var docs strings.Builder          // buffered; emitted after the code rows
for rows.Next() {
    ...
    out := b
    if kind == kindDoc { out = &docs }
    fmt.Fprintf(out, "  - %s : %s%s  (commit %s)\n    [%s] %s\n",
        path, symbol, docTag(kind), shortSHA(sha), where, excerpt)
}
if docs.Len() > 0 {
    b.WriteString("    -- documentation matches: PROSE from the repo's own docs,\n" +
                  "       NOT static-tier evidence. A doc SAYS a mechanism exists;\n" +
                  "       only code SHOWS it. Do not cite these as \"the code shows X\" --\n" +
                  "       follow them to the code and cite that.\n")
    b.WriteString(docs.String())
}
